#!/usr/bin/env bash
# Question 1: CronJob ${Q1_APP} never succeeds. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: batch/v1
kind: CronJob
metadata:
  name: ${Q1_APP}
  namespace: ${Q1_NS}
spec:
  schedule: "* * * * *"
  suspend: true
  successfulJobsHistoryLimit: 3
  failedJobsHistoryLimit: 3
  jobTemplate:
    spec:
      backoffLimit: 2
      template:
        spec:
          restartPolicy: Never
          containers:
            - name: report
              image: busybox:1.36
              command: ["sh", "-c", "date; sleep 8; echo report done"]
EOF
kubectl -n "${Q1_NS}" get cronjob "${Q1_APP}" -o jsonpath='{.metadata.uid}' > "/var/tmp/cka-q1.uid"
chmod 644 "/var/tmp/cka-q1.uid"

case "${Q1_FAULT}" in
  suspended) ;;
  never-schedule)
    kubectl -n "${Q1_NS}" patch cronjob "${Q1_APP}" --type=merge -p '{"spec":{"suspend":false,"schedule":"0 0 31 2 *"}}'
    ;;
  deadline)
    kubectl -n "${Q1_NS}" patch cronjob "${Q1_APP}" --type=merge -p '{"spec":{"suspend":false}}'
    kubectl -n "${Q1_NS}" patch cronjob "${Q1_APP}" --type=json -p '[{"op":"add","path":"/spec/jobTemplate/spec/activeDeadlineSeconds","value":3}]'
    ;;
  backoff-zero-command)
    kubectl -n "${Q1_NS}" patch cronjob "${Q1_APP}" --type=merge -p '{"spec":{"suspend":false}}'
    kubectl -n "${Q1_NS}" patch cronjob "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/jobTemplate/spec/backoffLimit","value":0},{"op":"replace","path":"/spec/jobTemplate/spec/template/spec/containers/0/command/2","value":"date; sleep 8; ech report done"}]'
    ;;
  image-registry)
    kubectl -n "${Q1_NS}" patch cronjob "${Q1_APP}" --type=merge -p '{"spec":{"suspend":false}}'
    kubectl -n "${Q1_NS}" patch cronjob "${Q1_APP}" --type=json -p '[{"op":"replace","path":"/spec/jobTemplate/spec/template/spec/containers/0/image","value":"registry.invalid/busybox:1.36"}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
